def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def newman_prime(n):
    if n <= 0:
        raise ValueError("n must be a positive integer")
    count = 0
    k = 2  # Start with k=2 because 3^1 - 1 = 2 is not considered a prime
    while count < n:
        number = (3 ** k) - 1
        if is_prime(number):
            count += 1
            if count == n:
                return number
        k += 1

